cd /work/output/artifacts/skill-flow-jdbc-databricks-query/DatabricksQuery/DatabricksQuery
DETAIL=$(cat <<'JSON'
{
  "connectionId": "4e5d613a-96be-4ba7-b86b-ebe225d192f1",
  "folderKey": "5da18ec0-7de1-4e57-aaf1-ddc8a369c199",
  "method": "POST",
  "endpoint": "/hubs/datawarehouse/query",
  "bodyParameters": {
    "script": "SELECT department, COUNT(*) AS employee_count, AVG(salary) AS average_salary FROM employees GROUP BY department HAVING COUNT(*) >= 2 ORDER BY average_salary"
  }
}
JSON
)
uip maestro flow node configure "DatabricksQuery.flow" "queryEmployeesByDepartment1" --detail "$DETAIL" --output json \
  && uip maestro flow validate "DatabricksQuery.flow" --output json \
  && uip maestro flow format "DatabricksQuery.flow" --output json

